from __future__ import annotations
import contextlib
import io
import json
import sys
from types import ModuleType

SOURCE = '#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""嵌入式工具链体检。\n\n接手一个新工程、写移植文档、或判断"这台机器能不能编这个工程"之前先跑一遍。\n只依赖标准库。\n\n用法:\n    python toolchain_check.py\n    python toolchain_check.py --json\n    python toolchain_check.py --tools armcc,armclang,arm-none-eabi-gcc,openocd\n    python toolchain_check.py --keil-root "D:/Keil_v5"\n\n退出码: 0=ok, 1=warn, 2=error（便于在脚本里做闸门）\n\n安全边界:\n  - 本脚本只读不写：不修改任何文件，不改系统状态。\n  - 会执行外部命令，但**只执行内置白名单 TOOLS 里的工具名**，且只传取版本的参数\n    （如 `--version` / `--vsn`）；不接受任意命令作为输入。\n  - `--tools` 只能从白名单里选；`--keil-root` 只用于拼 Keil 安装目录下的已知相对路径。\n  - 子进程输出一律先清洗（去控制字符 + 限长）再展示，不直接向下游上下文传递。\n"""\n\n\n\nimport argparse\nimport json\nimport os\nimport shutil\nimport subprocess\nimport sys\nfrom pathlib import Path\n\n# name -> (kind, 探测的可执行名列表, 版本参数, 常见路径候选模板)\n# {keil} 会被替换为 --keil-root（或其自动探测结果）\nTOOLS = {\n    "armcc": ("compiler-ac5", ["armcc", "armcc.exe"], ["--vsn"],\n              ["{keil}/ARM/ARMCC/bin/armcc.exe", "{keil}/ARM/ARMCC/bin/armcc"]),\n    "armclang": ("compiler-ac6", ["armclang", "armclang.exe"], ["--version"],\n                 ["{keil}/ARM/ARMCLANG/bin/armclang.exe"]),\n    "arm-none-eabi-gcc": ("compiler-gcc", ["arm-none-eabi-gcc"], ["--version"], []),\n    "gcc": ("compiler-host", ["gcc"], ["--version"], []),\n    "clang": ("compiler-host", ["clang"], ["--version"], []),\n    "make": ("build", ["make", "mingw32-make"], ["--version"], []),\n    "cmake": ("build", ["cmake"], ["--version"], []),\n    "ninja": ("build", ["ninja"], ["--version"], []),\n    "openocd": ("debug", ["openocd"], ["--version"], []),\n    "pyocd": ("debug", ["pyocd"], ["--version"], []),\n    "git": ("vcs", ["git"], ["--version"], []),\n    "python": ("runtime", ["python", "python3", "py"], ["--version"], []),\n    "UV4": ("ide", ["UV4", "UV4.exe"], [], ["{keil}/UV4/UV4.exe"]),\n}\n\n# 分类到"核心程度"：缺这些就是 error / warn\nCORE_COMPILERS = {"armcc", "armclang", "arm-none-eabi-gcc", "gcc", "clang"}\nCORE_BUILD = {"make", "cmake", "ninja"}\n\nKEIL_DEFAULTS = [\n    r"C:/Keil_v5", r"C:/Keil", r"D:/Keil_v5", r"D:/Keil",\n    r"C:/Program Files/Keil_v5", r"C:/Program Files (x86)/Keil_v5",\n    r"C:/Program Files/ARM/Keil_v5",\n]\n\n\ndef find_keil_root(explicit: str | None) -> str | None:\n    if explicit:\n        return explicit.replace("\\\\", "/").rstrip("/")\n    for env in ("KEIL_ROOT", "KEIL_HOME", "MDK_ROOT"):\n        v = os.environ.get(env)\n        if v and Path(v).exists():\n            return v.replace("\\\\", "/").rstrip("/")\n    for cand in KEIL_DEFAULTS:\n        if Path(cand).exists():\n            return cand\n    # 退化：UV4 已在 PATH 里时，用它的上一级\n    uv4 = shutil.which("UV4") or shutil.which("UV4.exe")\n    if uv4:\n        return str(Path(uv4).parent.parent).replace("\\\\", "/")\n    return None\n\n\ndef msys_to_win(p: str) -> str | None:\n    """Git Bash / MSYS 风格路径 (/c/Users/x) 转 Windows 风格 (C:/Users/x)。\n\n    实测踩过的坑：Git Bash 的 PATH 里会混进 MSYS 风格条目，而 shutil.which 走的是\n    Windows API，认不出这类条目——于是明明 python.exe 就在 PATH 里，探测结果却是"缺"。\n    探测工具必须覆盖这种路径风格，否则工具面会假性缺失。\n    """\n    if len(p) >= 3 and p[0] == "/" and p[2] == "/" and p[1].isalpha():\n        return f"{p[1].upper()}:/{p[2:]}"\n    return None\n\n\ndef which_any(name: str) -> str | None:\n    """先走 shutil.which，再在规范化后的 PATH 里按 PATHEXT 找一遍。"""\n    hit = shutil.which(name)\n    if hit:\n        return hit\n    exts = [e.strip() for e in os.environ.get("PATHEXT", ".EXE").split(";") if e.strip()]\n    cands = [name] + [name + e for e in exts]\n    for entry in os.environ.get("PATH", "").split(os.pathsep):\n        entry = msys_to_win(entry) or entry\n        if not entry:\n            continue\n        for c in cands:\n            full = Path(entry) / c\n            if full.is_file():\n                return str(full).replace("\\\\", "/")\n    return None\n\n\ndef sanitize(text: str, limit: int = 120) -> str:\n    """清洗外部输出：去掉控制字符（保留 Tab）并限长。\n\n    子进程输出属于外部数据，不静默原样透传到下游（日志/JSON/终端）。\n    """\n    clean = "".join(ch for ch in text\n                    if ch == "\\t" or ord(ch) >= 32 or ch == " ")\n    return clean.replace("\\x7f", "").strip()[:limit]\n\n\ndef run_version(exe: str, args: list[str], timeout: int = 10) -> str:\n    if not args:\n        return ""\n    try:\n        p = subprocess.run([exe, *args], capture_output=True, timeout=timeout)\n    except (OSError, subprocess.SubprocessError) as exc:\n        return f"<无法执行: {type(exc).__name__}>"\n    for stream in (p.stdout, p.stderr):\n        if not stream:\n            continue\n        text = stream.decode("utf-8", errors="replace").strip()\n        for line in text.splitlines():\n            line = line.strip()\n            if line:\n                return sanitize(line)\n    return ""\n\n\ndef probe(name: str, spec, keil_root: str | None) -> dict:\n    kind, names, ver_args, tmpl = spec\n    rec = {"name": name, "kind": kind, "found": False, "path": None, "version": ""}\n\n    # python 特判：当前解释器一定可用，比在 PATH 里碰运气可靠\n    if name == "python" and sys.executable and Path(sys.executable).exists():\n        rec.update(found=True, path=sys.executable.replace("\\\\", "/"))\n        rec["version"] = run_version(sys.executable, ["--version"])\n        return rec\n\n    for n in names:\n        # py 是 Windows 的启动器：用 py -3 才是真解释器\n        hit = which_any(n)\n        if hit:\n            rec.update(found=True, path=hit)\n            if n == "py":\n                rec["version"] = run_version(hit, ["-3", "--version"]) or rec["version"]\n                if not rec["version"]:\n                    continue\n            else:\n                rec["version"] = run_version(hit, ver_args)\n            return rec\n\n    if keil_root:\n        for t in tmpl:\n            cand = Path(t.replace("{keil}", keil_root))\n            if cand.exists():\n                rec.update(found=True, path=str(cand).replace("\\\\", "/"))\n                rec["version"] = run_version(str(cand), ver_args)\n                return rec\n    return rec\n\n\ndef summarize(records: list[dict]) -> tuple[str, list[str]]:\n    notes: list[str] = []\n    found = {r["name"] for r in records if r["found"]}\n    compilers = sorted(found & CORE_COMPILERS)\n    has_build = bool(found & CORE_BUILD)\n\n    if not compilers:\n        return "error", ["未找到任何 C 编译器——先装工具链，再谈编译工程"]\n\n    if not has_build:\n        notes.append("有编译器但没有 make/cmake/ninja：命令行构建链路不完整")\n        return "warn", notes\n\n    # AC5 / AC6 同时存在：这是最容易混用判断的组合，必须提醒\n    if {"armcc", "armclang"} <= found:\n        notes.append("AC5(armcc) 与 AC6(armclang) 同时存在："\n                     "同一份源码两者行为可能不同，判断问题时必须先声明用的是哪一套")\n\n    if "armcc" in found and "armclang" not in found:\n        notes.append("只有 AC5(armcc)：它不认 __has_include 等新特性，"\n                     "条件包含与扩展行为要按 AC5 判")\n\n    return ("ok", notes) if not notes else ("warn", notes)\n\n\ndef main(argv: list[str] | None = None) -> int:\n    ap = argparse.ArgumentParser(description="嵌入式工具链体检")\n    ap.add_argument("--tools", default="",\n                    help="只查这些工具，逗号分隔；默认全部")\n    ap.add_argument("--keil-root", default=None, help="Keil/MDK 安装根目录")\n    ap.add_argument("--json", action="store_true", help="输出 JSON")\n    args = ap.parse_args(argv)\n\n    wanted = [t.strip() for t in args.tools.split(",") if t.strip()] or list(TOOLS)\n    unknown = [t for t in wanted if t not in TOOLS]\n    if unknown:\n        print(f"未知工具名: {\', \'.join(unknown)}；可用: {\', \'.join(TOOLS)}", file=sys.stderr)\n        return 2\n\n    keil_root = find_keil_root(args.keil_root)\n    records = [probe(t, TOOLS[t], keil_root) for t in wanted]\n    verdict, notes = summarize(records)\n\n    if args.json:\n        print(json.dumps({\n            "verdict": verdict,\n            "keil_root": keil_root,\n            "tools": records,\n            "notes": notes,\n        }, ensure_ascii=False, indent=2))\n        return {"ok": 0, "warn": 1, "error": 2}[verdict]\n\n    print(f"keil_root: {keil_root or \'<未找到>\'}")\n    print(f"{\'工具\':<20}{\'类别\':<15}{\'状态\':<6}版本 / 路径")\n    print("-" * 100)\n    for r in records:\n        status = "有" if r["found"] else "缺"\n        detail = r["version"] or (r["path"] or "")\n        if r["found"] and r["path"] and r["version"]:\n            detail = f"{r[\'version\']}  @ {r[\'path\']}"\n        print(f"{r[\'name\']:<20}{r[\'kind\']:<15}{status:<6}{detail}")\n    print("-" * 100)\n    print(f"verdict: {verdict}")\n    for n in notes:\n        print(f"  ! {n}")\n    if verdict != "ok":\n        print("  → 结论：环境不完整或需注意工具链混用；不要凭印象判断编译行为")\n    return {"ok": 0, "warn": 1, "error": 2}[verdict]\n\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'

def main():
    capture, errors = io.StringIO(), io.StringIO()
    code = 0
    try:
        request = json.load(sys.stdin)
        args = request.get('args')
        if not isinstance(args, list) or any(not isinstance(x, str) for x in args):
            raise ValueError('args_must_be_string_list')
        sys.argv = ['toolchain_check.py'] + args
        module = ModuleType('__main__')
        module.__file__ = 'toolchain_check.py'
        sys.modules['__main__'] = module
        with contextlib.redirect_stdout(capture), contextlib.redirect_stderr(errors):
            exec(compile(SOURCE, 'toolchain_check.py', 'exec'), module.__dict__)
    except SystemExit as error:
        code = error.code if isinstance(error.code, int) else 1
    except Exception as error:
        code = 1
        errors.write(type(error).__name__ + ': ' + str(error))
    print(json.dumps({'exit_code': code, 'stdout': capture.getvalue(), 'stderr': errors.getvalue()}, ensure_ascii=False))
    return code

if __name__ == '__main__':
    raise SystemExit(main())
